package com.fakelegacy.order.web;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

import com.fakelegacy.order.client.CustomerClient;
import com.fakelegacy.order.client.CustomerSnapshot;
import com.fakelegacy.order.client.RemoteResult;
import com.fakelegacy.order.domain.Cart;
import com.fakelegacy.order.domain.Order;
import com.fakelegacy.order.repo.CartRepository;
import com.fakelegacy.order.service.OrderManager;
import com.fakelegacy.order.web.ApiRequests.CheckoutRequest;

@RestController
public class CheckoutController {

    @Autowired
    private CartRepository carts;
    @Autowired
    private CustomerClient customerClient;
    @Autowired
    private OrderManager orderManager;

    // O4
    @PostMapping("/carts/{id}/checkout")
    public ResponseEntity<Object> checkout(@PathVariable("id") Long id,
            @RequestBody(required = false) CheckoutRequest req) {
        Cart cart = carts.findById(id).orElse(null);
        if (cart == null) {
            return ResponseEntity.notFound().build();
        }
        if (req == null) {
            return ResponseEntity.badRequest().body(message("shippingMethod is required"));
        }
        if (!Cart.OPEN.equals(cart.getStatus())) {
            return ResponseEntity.badRequest().body(message("cart is already checked out"));
        }
        if (cart.getLines().isEmpty()) {
            return ResponseEntity.badRequest().body(message("the cart is empty"));
        }

        RemoteResult cr = customerClient.getCustomer(cart.getCustomerId());
        if (!cr.isOk()) {
            return ResponseEntity.badRequest().body(message("customer lookup failed: " + cr.getMessage()));
        }
        CustomerSnapshot customer = CustomerSnapshot.from(cr.getBody());
        if (customer.isBlacklisted()) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).body(message("customer is blacklisted"));
        }

        String country = customer.getDefaultCountry();
        if (country == null) {
            return ResponseEntity.badRequest().body(message("customer has no default shipping address"));
        }
        BigDecimal surcharge;
        if (country.equals("FR")) {
            surcharge = BigDecimal.ZERO.setScale(2);
        } else if (country.equals("BE") || country.equals("LU")) {
            surcharge = new BigDecimal("5.00");
        } else {
            return ResponseEntity.badRequest().body(message("shipping to " + country + " is not supported"));
        }

        Order order = orderManager.checkout(cart, req, customer, surcharge);
        return ResponseEntity.status(HttpStatus.CREATED).body(order);
    }

    private Map<String, Object> message(String text) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("message", text);
        return m;
    }
}
